const JFL=['Assigned','Out for delivery','Delivered'];
CP['jup:deliv']=()=>`${isAdm()||S.me==='zubair'?`<button class="btn w" data-a="jNew" style="margin-bottom:12px">${ic('plus')}New order</button>`:''}`+D.jord.map(o=>`<div class="card"><div class="row nw"><div style="flex:1"><b class="num" style="font-size:16px">${o.id} · ${h(o.item)}</b><div class="xs mut">${h(o.cust)} · from ${h(o.from)} · ${h(nmF(o.boy))}</div></div><b class="num">${inr(o.transport)}</b></div>${trk(JFL,o.st==='Delivered'?3:JFL.indexOf(o.st))}<div class="row" style="margin-top:6px"><span class="xs mut">KYC</span>${['Name','Phone','Aadhaar','Photo + map'].map((x,i)=>pill(x,i<o.kyc?'g':'')).join('')}<span class="sp"></span>${o.st!=='Delivered'?`<button class="btn sm" data-a="jNext" data-id="${o.id}">${o.st==='Assigned'?'Start':'Delivered + KYC'}</button>`:''}</div></div>`).join('')+`<div class="note">Rent is paid on Jupiter's QR; transport comes to JDAC (bed ₹1,500–2,000; wheelchair, oxygen, walker ₹500 — Nadeem can adjust).</div>`;
CP['jup:equip']=()=>{S.je=S.je||'Rented';const ST=['Available','Rented','Return pending','Repair','Expired'];return chips(ST.map(s=>[s,s,D.jinv.filter(x=>x.st===s).length]),S.je,'je')+(S.je==='Rented'?`<div class="card" style="margin-top:12px;padding:0;overflow:hidden"><div style="position:relative;height:230px;background:linear-gradient(135deg,#e6f0f4,#d8e7ee)" role="img" aria-label="Map of rented equipment in Pune">${D.jinv.filter(x=>x.x).map(x=>`<button data-a="toast" data-t="${h(x.sn)} · ${h(x.t)} · ${h(x.cust)}" style="position:absolute;left:${x.x}%;top:${x.y}%;transform:translate(-50%,-100%);border:0;background:var(--navy);color:#fff;font:700 11px Inter;border-radius:8px;padding:3px 7px">${x.sn}</button>`).join('')}</div></div>`:'<div style="margin-top:12px"></div>')+`<div class="list">${D.jinv.filter(x=>x.st===S.je).map(x=>`<div class="li"><div class="av" style="background:#139B5F;border-radius:12px">${ic('bed')}</div><div class="tx"><b>${x.sn} · ${h(x.t)}</b><div class="m">${x.cust?h(x.cust)+' · ends '+fmt(x.end):'In warehouse'}</div></div></div>`).join('')||empty('None')}</div>`};
CP['jup:renew']=()=>{const R=D.jinv.filter(x=>x.end&&x.st!=='Available').sort((a,b)=>a.end.localeCompare(b.end));return `<div class="list">${R.map(x=>{const d=daysTo(x.end);return `<div class="li"><div class="tx"><b>${x.sn} · ${h(x.t)}</b><div class="m">${h(x.cust)} · ${d<0?`<b style="color:var(--r)">${-d}d overdue</b>`:d+' days left'}</div></div><button class="btn sm" data-a="renew" data-id="${x.sn}">Renew</button><button class="btn sm sec" data-a="retPend" data-id="${x.sn}">Return</button></div>`}).join('')}</div><div class="note">Shows from 7 days before the end date. Jupiter calls the customer; Zubair or Jupiter (own login) update it here.</div>`};
CP['jup:exp']=()=>`<button class="btn w" data-a="expNew" style="margin-bottom:12px">${ic('plus')}Add expense</button><div class="list">${D.vch.filter(v=>v.co==='jup'&&v.ty==='Expense').map(vRow).join('')}</div>${pettyBlock('pune-wh')}<div class="note">Porter is booked from the company wallet. Rapido & labour: delivery boy sends QR → Zubair approves → Snehal Z or Nameera pays from Pune petty cash. TA ₹3/km on own vehicle.</div>`;
CP['jup:settle']=()=>{const rent=6300-1800;return `<div class="stats"><div><b>${inr(1800)}</b><span>transport to JDAC</span></div><div><b>${inr(rent)}</b><span>rent on Jupiter QR</span></div><div><b>₹1.75L</b><span>or 15% of revenue · higher</span></div></div><div class="list">${D.vch.filter(v=>v.co==='jup'&&(v.ty==='Receipt'||v.ty==='Journal')).map(vRow).join('')}</div><div class="note">Month end: money that reached the wrong account (rent to JDAC or transport to Jupiter) is matched here instead of a spreadsheet, and Jupiter verifies from its own login. The warehouse fee is billed by JDAC Studios.</div>`};
/* HR */
const HFL=['Shortlisted','Shared','Interview','Selected','Joined'];
CP['hr:hire']=()=>D.hire.map(x=>`<div class="card"><div class="row nw">${av(x.n)}<div style="flex:1"><b>${h(x.n)}</b><div class="xs mut">${h(x.job)} · ${h(x.co)}</div></div>${x.day?pill('Day '+x.day+' of 30','g'):''}</div>${trk(HFL,HFL.indexOf(x.st)+(x.st==='Joined'?1:0))}</div>`).join('')+`<div class="note">Nameera and Snehal B both work employers and candidates for now. The full HR portal (company + candidate logins, check-ins Day 1/7/15/30, fair-play scores both ways) gets merged here. Feed is parked.</div>`;
CP['hr:cos']=()=>`<div class="list">${D.hrco.map((c,i)=>`<div class="li" style="flex-wrap:wrap"><div class="tx" style="min-width:180px"><b>${h(c.n)}</b><div class="m">${h(c.st)} · 50/50 split · no replacement</div></div><label class="sr" for="hf${i}">Fee</label><select id="hf${i}" data-ch="hrfee" data-i="${i}" style="width:auto;min-height:38px">${[50,75,100].map(x=>`<option value="${x}" ${c.plan.fee===x?'selected':''}>${x}% salary</option>`).join('')}</select><span class="sm">Day</span><input type="number" value="${c.plan.a}" data-ch="hra" data-i="${i}" style="width:64px;min-height:38px" aria-label="First payment day"><span class="sm">+ Day</span><input type="number" value="${c.plan.b}" data-ch="hrb" data-i="${i}" style="width:64px;min-height:38px" aria-label="Second payment day"></div>`).join('')}</div><div class="note">Fee % and both payment days are set per company at onboarding and can be edited. Our own five companies hire through the same panel with no fee.</div>`;
CP['hr:wallet']=()=>`<div class="hero" style="background:linear-gradient(135deg,#7A2E8E,#A458B8)"><div class="xs" style="font-weight:700">EMPLOYER OFFER</div><div class="big" style="font-size:34px;margin-top:6px">₹999 → wallet</div><div class="sm" style="margin-top:6px">Recharge up to ₹10,000 and get 100% cashback — usable only for hiring fees.</div></div><div class="note">One central wallet across GovaaBazaar, Logistics and HR, kept simple in the background. The statement is in Accounts → Parties.</div>`;
CP['studios:clients']=()=>`<div class="list">${D.clients.map((c,i)=>`<div class="li"><div class="av" style="background:${colr(c.n)};border-radius:12px">${h(ini(c.n))}</div><div class="tx"><b>${h(c.n)}</b><div class="m">${h(c.fee)}</div></div>${c.auto?(c.st.startsWith('Ready')&&isAcc()?`<button class="btn sm" data-a="clSend" data-i="${i}">Send invoice</button>`:pill(c.st.split(' · ')[0],c.st.startsWith('Sent')?'g':'a')):pill('Internal ₹0','p')}</div>`).join('')}</div><div class="note">Invoices are made automatically on the 1st and wait for Snehal Z before "Send to customer" (email from her own @jdac.in ID).</div>`;
CP['studios:ads']=()=>`<div class="list">${['JDAC Logistics','GovaaBazaar','HR Consultancy','Jupiter Pune','Retailer & Distributor Bazaar','Bahiram'].map(x=>`<div class="li">${av(x)}<div class="tx"><b>${x}</b><div class="m">Om Parvate · own ad account</div></div>${pill('Connect Meta')}</div>`).join('')}</div><div class="note">Each company has its own ad account, so leads and spend map to the right company. GovaaBazaar goal: about ₹100 per order.</div>`;

/* =================== ACCOUNTS =================== */
const VTY={Sale:['g','rupee'],Receipt:['g','rupee'],Purchase:['b','box'],Expense:['r','rupee'],'Credit note':['a','doc'],'Debit note':['p','doc'],'Cash deposit':['t','bank'],Journal:['','doc']};
const acctName=id=>{const b=D.banks.find(x=>x.id===id);if(b)return b.n+' '+b.no;const p=D.petty.find(x=>'c-'+x.id===id);return p?'Cash · '+p.n:(id||'—')};
function bankBal(b){return D.vch.filter(v=>v.acct===b.id&&v.st==='Verified').reduce((a,v)=>a+(['Receipt','Cash deposit'].includes(v.ty)||(v.ty==='Sale'&&v.mode!=='Credit'&&!D.vch.some(r=>r.ref===v.id))?v.amt:['Purchase','Expense'].includes(v.ty)&&v.mode!=='Credit'?-v.amt:0),b.open)}
function recon(b){const L=(D.stmt[b.id]||[]);return L.length?pct(L.filter(l=>l.m).length,L.length):100}
const cashTotal=()=>D.petty.reduce((a,p)=>a+p.hold,0);
const recv=()=>D.vch.filter(v=>v.ty==='Sale'&&v.st==='Verified'&&(v.paid||0)<v.amt);
const payb=()=>D.vch.filter(v=>v.ty==='Purchase'&&v.mode==='Credit'&&!v.settled);
const gstOf=v=>v.gst?Math.round(v.amt*v.gst/(100+v.gst)):0;
function vRow(v){const c=VTY[v.ty]||['',''];const sign=['Receipt','Sale','Cash deposit'].includes(v.ty)?'+':['Purchase','Expense','Credit note'].includes(v.ty)?'−':'';
 return `<button class="li" data-a="vOpen" data-id="${v.id}"><div class="av" style="background:var(--${c[0]||'navy'}L,var(--bg));color:var(--${c[0]||'navy'});border-radius:12px;${c[0]?'':'background:var(--bg);color:var(--navy)'}">${ic(c[1]||'doc')}</div><div class="tx"><b>${h(v.party)}</b><div class="m">${h(v.ty)} · ${h(coShort(v.co))} · ${fmt(v.dt)} · ${v.by==='System'?'auto':h(nmF(v.by))}${v.file?' · 📎':''}</div></div><div style="text-align:right"><div class="amt" style="color:${sign==='+'?'var(--g)':sign==='−'?'var(--r)':'inherit'}">${sign}${inr(v.amt)}</div>${v.st!=='Verified'?pill(v.st,v.st==='Split needed'?'r':'a'):''}</div></button>`}
function bRow(b){return `<button class="li" data-a="bankOpen" data-id="${b.id}"><div class="av" style="background:var(--navy);border-radius:12px">${ic('bank')}</div><div class="tx"><b>${h(b.n)} ${h(b.no)}</b><div class="m">${h(BOOKS[b.co])} · ${recon(b)}% matched</div></div><b class="amt">${inr(bankBal(b))}</b></button>`}
function balHero(){const bank=D.banks.reduce((a,b)=>a+bankBal(b),0),cash=cashTotal();return `<div class="hero" style="background:linear-gradient(135deg,#0f3b2c,#139B5F)"><div class="xs" style="font-weight:700;opacity:.9">CASH + BANK · RIGHT NOW</div><div class="big" style="margin-top:6px">${inr(bank+cash)}</div><div class="sm" style="opacity:.9">Bank ${inr(bank)} · Cash in hand ${inr(cash)} · updates as entries are verified</div></div>`}
V.money=()=>{const t=S.mtab,bk=S.mbk;const inB=v=>!bk||v.co===bk;
 const W=D.vch.filter(v=>(v.st==='To verify'||v.st==='Split needed')&&inB(v));
 const head=page('Accounts','Replaces Tally · every company\'s books in one place · staff entries come here to verify',`<button class="btn" data-a="vNew">${ic('plus')}New entry</button>`)+
 chips([['overview','Overview'],['verify','Verify',W.length],['vch','Entries'],['bank','Bank & cash'],['party','Parties'],['recv','To collect'],['pay','To pay'],['gst','GST'],['rep','Reports']],t,'mtab')+`<div style="margin:10px 0 12px">${chips([['','All companies'],...Object.keys(BOOKS).map(k=>[k,coShort(k)])],bk,'mbk')}</div>`;
 if(t==='overview'){const R=recv().filter(inB),PB=payb().filter(inB),gst=Object.keys(BOOKS).filter(k=>!bk||k===bk).reduce((a,k)=>a+gstNet(k),0);const ks=Object.keys(BOOKS).filter(k=>!bk||k===bk),tot=ks.reduce((a,k)=>[a[0]+D.pl[k][0],a[1]+D.pl[k][1]],[0,0]);
  return head+balHero()+`<div class="stats"><button data-a="mtab" data-t="recv" style="border:0;text-align:left;background:#fff;border-radius:16px;padding:12px 14px;box-shadow:var(--sh);flex:1 0 140px"><b style="font:800 22px Outfit;display:block;color:var(--o2)">${inr(R.reduce((a,v)=>a+v.amt-(v.paid||0),0))}</b><span class="xs mut" style="font-weight:600">to collect · ${R.length} bills</span></button><button data-a="mtab" data-t="pay" style="border:0;text-align:left;background:#fff;border-radius:16px;padding:12px 14px;box-shadow:var(--sh);flex:1 0 140px"><b style="font:800 22px Outfit;display:block;color:var(--r)">${inr(PB.reduce((a,v)=>a+v.amt,0))}</b><span class="xs mut" style="font-weight:600">to pay · ${PB.length} bills</span></button><button data-a="mtab" data-t="gst" style="border:0;text-align:left;background:#fff;border-radius:16px;padding:12px 14px;box-shadow:var(--sh);flex:1 0 140px"><b style="font:800 22px Outfit;display:block">${inr(gst)}</b><span class="xs mut" style="font-weight:600">GST payable</span></button><button data-a="mtab" data-t="verify" style="border:0;text-align:left;background:#fff;border-radius:16px;padding:12px 14px;box-shadow:var(--sh);flex:1 0 140px"><b style="font:800 22px Outfit;display:block;color:var(--a)">${W.length}</b><span class="xs mut" style="font-weight:600">entries to verify</span></button></div>
  ${isAdm()?`${st('This month · profit & loss')}<div class="list">${ks.map(k=>{const p=D.pl[k],m=pct(p[0]-p[1],p[0]);return `<button class="li" data-a="mbk" data-t="${k}"><div class="av" style="background:${CO[k].c};border-radius:12px">${ic(CO[k].ic)}</div><div class="tx"><b>${BOOKS[k]}</b><div class="m">Sales ${inr(p[0])} · costs ${inr(p[1])}</div><div class="bar g" style="margin-top:5px"><i style="width:${m}%"></i></div></div><div style="text-align:right"><b class="amt">${inr(p[0]-p[1])}</b><div class="xs mut">${m}% margin</div></div></button>`}).join('')}<div class="li"><div class="tx"><b>Total</b></div><b class="amt">${inr(tot[0]-tot[1])}</b></div></div>`:''}
  ${st('Bank accounts',`<button class="lnk" data-a="mtab" data-t="bank">Open</button>`)}<div class="list">${D.banks.filter(b=>inB(b)).map(bRow).join('')}</div>
  ${st('Latest entries',`<button class="lnk" data-a="mtab" data-t="vch">All</button>`)}<div class="list">${D.vch.filter(inB).slice().sort((a,b)=>b.dt.localeCompare(a.dt)).slice(0,6).map(vRow).join('')}</div>`}
 if(t==='verify')return head+`<div class="note">Entries made by staff (receipts with photos, expenses, goods inward, returns, cash deposits) wait here. Verifying updates bank / cash balances and the books.</div><div class="list">${W.map(v=>`<div class="li" style="flex-wrap:wrap">${vRow(v).replace(/^<button class="li"/,'<button class="li" style="padding:0;border:0;flex:1;min-width:240px"')}<div class="row" style="gap:6px">${v.st==='Split needed'?`<button class="btn sm" data-a="vSplit" data-id="${v.id}">Split</button>`:`<button class="btn sm g" data-a="vOk" data-id="${v.id}">Verify</button>`}<button class="btn sm sec" data-a="vNo" data-id="${v.id}">Reject</button></div></div>`).join('')||empty('All verified ✓')}</div>`;
 if(t==='vch'){S.vt=S.vt||'';const L=D.vch.filter(v=>inB(v)&&(!S.vt||v.ty===S.vt)).sort((a,b)=>b.dt.localeCompare(a.dt));return head+chips([['','All types'],...Object.keys(VTY).map(k=>[k,k,D.vch.filter(v=>inB(v)&&v.ty===k).length])],S.vt,'vt')+`<div class="list" style="margin-top:12px">${L.map(vRow).join('')||empty('No entries')}</div>`}
 if(t==='bank'){if(S.bk){const b=D.banks.find(x=>x.id===S.bk);if(b){const L=D.stmt[b.id]||[];return head+`<button class="lnk" data-a="bankX">${ic('back')} All accounts</button><div class="card"><div class="row nw"><div class="av l" style="background:var(--navy);border-radius:14px">${ic('bank')}</div><div style="flex:1"><b style="font-size:17px">${h(b.n)} ${h(b.no)}</b><div class="xs mut">${h(BOOKS[b.co])} · ${recon(b)}% of statement matched</div></div><div style="text-align:right"><div class="num" style="font-size:24px;font-weight:800">${inr(bankBal(b))}</div><div class="xs mut">book balance</div></div></div><label class="btn sec w" style="margin-top:12px;cursor:pointer">${ic('up')}Upload statement / passbook (PDF, Excel, photo)<input type="file" class="sr" data-ch="stmt" data-b="${b.id}" accept=".pdf,.xls,.xlsx,.csv,image/*"></label></div>${st('Statement lines')}<div class="list">${L.map((l,i)=>`<div class="li"><div class="tx"><b>${h(l.desc)}</b><div class="m">${fmt(l.d)} · ${l.m?'matched to '+h((D.vch.find(v=>v.id===l.m)||{}).party||l.m):'not matched yet'}</div></div><b class="amt" style="color:${l.amt<0?'var(--r)':'var(--g)'}">${l.amt<0?'−':'+'}${inr(Math.abs(l.amt))}</b>${l.m?pill('✓','g'):`<button class="btn sm" data-a="lineMatch" data-b="${b.id}" data-i="${i}">Match</button>`}</div>`).join('')||empty('No statement uploaded yet')}</div>`}}
  return head+`${balHero()}${st('Bank accounts')}<div class="list">${D.banks.filter(inB).map(bRow).join('')}</div>${st('Cash in hand')}<div class="list">${D.petty.map(p=>`<div class="li"><div class="av" style="background:var(--aL);color:var(--a);border-radius:12px">${ic('rupee')}</div><div class="tx"><b>${h(p.n)}</b><div class="m">${p.lines.length} entries · deposit slips reduce it</div></div><b class="amt">${inr(p.hold)}</b></div>`).join('')}</div><div class="note">Bank balance = opening + every verified receipt, payment, expense and deposit. Uploading the bank statement matches lines automatically by amount; anything left is matched by hand or turned into a new entry.</div>`}
 if(t==='party'){const map={};D.vch.filter(inB).forEach(v=>{if(['Cash deposit','Journal'].includes(v.ty))return;const m=map[v.party]||(map[v.party]={n:v.party,co:v.co,bal:0,cnt:0,kind:''});m.cnt++;const s={Sale:1,Receipt:-1,'Credit note':-1,Purchase:-1,'Debit note':1,Expense:0}[v.ty]||0;if(v.ty==='Sale')m.kind='Customer';if(v.ty==='Purchase')m.kind='Supplier';if(v.ty==='Expense'&&!m.kind)m.kind='Expense head';m.bal+=s*v.amt});
  const L=Object.values(map).sort((a,b)=>Math.abs(b.bal)-Math.abs(a.bal));return head+`<div class="list">${L.map(m=>`<button class="li" data-a="ledger" data-n="${h(m.n)}">${av(m.n)}<div class="tx"><b>${h(m.n)}</b><div class="m">${m.kind||'Party'} · ${coShort(m.co)} · ${m.cnt} entries</div></div><b class="amt" style="color:${m.bal>0?'var(--o2)':m.bal<0?'var(--r)':'var(--mut)'}">${m.bal?inr(Math.abs(m.bal))+(m.bal>0?' Dr':' Cr'):'Settled'}</b></button>`).join('')}</div><div class="note">Dr = they owe us · Cr = we owe them. Tap a party for its full ledger with running balance. Customer wallets (HR, Logistics, GovaaBazaar) sit here too.</div>`}
 if(t==='recv'){const R=recv().filter(inB);const age=v=>-daysTo(v.dt),bkt=[['0–7 days',v=>age(v)<=7],['8–30 days',v=>age(v)>7&&age(v)<=30],['Over 30 days',v=>age(v)>30]];
  return head+`<div class="glance" style="grid-template-columns:repeat(3,minmax(0,1fr))">${bkt.map(([l,f],i)=>`<div><b style="color:${i===2?'var(--r)':i===1?'var(--a)':'var(--g)'}">${inr(R.filter(f).reduce((a,v)=>a+v.amt-(v.paid||0),0))}</b><span>${l}</span></div>`).join('')}</div><div class="list">${R.sort((a,b)=>a.dt.localeCompare(b.dt)).map(v=>`<div class="li"><div class="tx"><b>${h(v.party)}</b><div class="m">${h(BOOKS[v.co])} · ${age(v)} days · ${h(v.src)}</div></div><b class="amt">${inr(v.amt-(v.paid||0))}</b><button class="btn sm sec" data-a="toast" data-t="WhatsApp reminder sent to ${h(v.party)}">Remind</button></div>`).join('')||empty('Nothing to collect')}</div><div class="note">GovaaBazaar credit is allowed up to 1 month (aim: 7 days). Over 30 days blocks the next delivery.</div>`}
 if(t==='pay'){const PB=payb().filter(inB);return head+`<div class="list">${PB.map(v=>`<div class="li"><div class="tx"><b>${h(v.party)}</b><div class="m">${h(BOOKS[v.co])} · ${h(v.src)} · due ${fmt(v.due||addD(v.dt,15))}</div></div><b class="amt">${inr(v.amt)}</b><button class="btn sm" data-a="paySup" data-id="${v.id}">Pay</button></div>`).join('')||empty('Nothing to pay')}</div><div class="note">Suppliers: Prakash Foods (running purchase ledger), carriers (Delhivery, DP World, ShipMozo, Routx), Jupiter settlement, Porter.</div>`}
 if(t==='gst')return head+`<div class="list">${Object.keys(BOOKS).filter(k=>!bk||k===bk).map(k=>{const o=gstOut(k),i=gstIn(k);return `<div class="li"><div class="av" style="background:${CO[k].c};border-radius:12px">${ic(CO[k].ic)}</div><div class="tx"><b>${BOOKS[k]}</b><div class="m">Output ${inr(o)} · input credit ${inr(i)}</div></div><b class="amt">${inr(Math.max(0,o-i))}</b></div>`}).join('')}</div><div class="grid g2"><button class="btn sec" data-a="toast" data-t="GSTR-1 export prepared for the CA (sample)">${ic('doc')}Export GSTR-1</button><button class="btn sec" data-a="toast" data-t="GSTR-3B summary prepared for the CA (sample)">${ic('doc')}Export GSTR-3B</button></div><div class="note">GST is worked out from every sale, purchase, expense, credit note and debit note. The CA gets a ready export instead of a Tally backup.</div>`;
 // reports
 const bank=D.banks.reduce((a,b)=>a+bankBal(b),0),stock=Object.entries(D.inv.goa).concat(Object.entries(D.inv.nashik)).reduce((a,[p,q])=>a+q*prd(p).cost,0),rc=recv().reduce((a,v)=>a+v.amt-(v.paid||0),0),pb=payb().reduce((a,v)=>a+v.amt,0),gst=Object.keys(BOOKS).reduce((a,k)=>a+gstNet(k),0),assets=bank+cashTotal()+rc+stock,liab=pb+gst;
 return head+`${st('Balance sheet · today')}<div class="grid g2"><div class="list" style="margin:0"><div class="grp">Assets</div>${[['Bank',bank],['Cash in hand',cashTotal()],['To collect',rc],['Stock (at cost)',stock]].map(r=>`<div class="li"><div class="tx"><b style="font-weight:500">${r[0]}</b></div><b class="amt">${inr(r[1])}</b></div>`).join('')}<div class="li"><div class="tx"><b>Total</b></div><b class="amt">${inr(assets)}</b></div></div><div class="list" style="margin:0"><div class="grp">Liabilities & capital</div>${[['To pay suppliers',pb],['GST payable',gst],['Capital & reserves',assets-liab]].map(r=>`<div class="li"><div class="tx"><b style="font-weight:500">${r[0]}</b></div><b class="amt">${inr(r[1])}</b></div>`).join('')}<div class="li"><div class="tx"><b>Total</b></div><b class="amt">${inr(assets)}</b></div></div></div>
 ${st('Reports')}<div class="list">${[['Profit & loss · company-wise','Monthly, quarterly, yearly'],['Daily summary','9:00 pm to Darshan · app + email'],['Weekly review','Saturday'],['Day book','Every entry by date'],['Stock audit','Every 10 days · last '+fmt(D.audit.last)+' · '+D.audit.marks.length+' mismatch (Atmaram)'],['Export for CA','Excel / Tally format']].map(r=>`<button class="li" data-a="toast" data-t="${h(r[0])} (sample)"><div class="av" style="background:var(--bg);color:var(--navy);border-radius:12px">${ic('doc')}</div><div class="tx"><b>${r[0]}</b><div class="m">${h(r[1])}</div></div>${ic('right')}</button>`).join('')}</div>
 ${st('Audit trail')}<div class="list">${D.alog.slice(-8).reverse().map(a=>`<div class="li"><div class="tx"><b style="font-weight:500">${h(a.t)}</b><div class="m">${h(nm(a.who))} · ${fmt(a.at)}</div></div></div>`).join('')}</div>`};
const gstOut=k=>D.vch.filter(v=>v.co===k&&v.ty==='Sale'&&v.st==='Verified').reduce((a,v)=>a+gstOf(v),0)-D.vch.filter(v=>v.co===k&&v.ty==='Credit note').reduce((a,v)=>a+gstOf(v),0);
const gstIn=k=>D.vch.filter(v=>v.co===k&&['Purchase','Expense'].includes(v.ty)&&v.st==='Verified').reduce((a,v)=>a+gstOf(v),0)-D.vch.filter(v=>v.co===k&&v.ty==='Debit note').reduce((a,v)=>a+gstOf(v),0);
const gstNet=k=>Math.max(0,gstOut(k)-gstIn(k));
function addV(o){const v=Object.assign({id:nid('V-'),dt:TODAY,gst:0,by:S.me,st:isAcc()?'Verified':'To verify',src:'',mode:'Cash',acct:''},o);D.vch.unshift(v);return v}
function logA(t){D.alog.push({at:TODAY,who:S.me,t})}

/* =================== PEOPLE =================== */
function seedNum(k,a,b){const s=[...k].reduce((x,c)=>x+c.charCodeAt(0),0);return a+s%(b-a+1)}
function kpiRows(){return STAFF.filter(k=>!['darshan','nameera','snehalz'].includes(k)).map(k=>{const T=D.tasks.filter(t=>t.o===k),done=T.filter(t=>t.st==='Done').length,late=T.filter(t=>t.st!=='Done'&&t.due<TODAY).length;const tg=D.targets.find(t=>t.who===k);const num=tg?pct(tg.v,tg.goal):seedNum(k,55,95);const tsk=T.length?pct(T.length-late,T.length):seedNum(k,60,100);const s=Math.round(num*.7+tsk*.3);return {k,s,num,tsk,why:late?late+' task'+(late>1?'s':'')+' late':tg&&num<60?'Target at '+num+'%':'Attendance: '+seedNum(k,1,3)+' late marks'}}).sort((a,b)=>b.s-a.s)}
V.people=()=>{const t=S.ptab;const head=page('People','Attendance, onboarding, leave and rules for our own staff',`<button class="btn" data-a="onbNew">${ic('plus')}Add joiner</button>`)+chips([['today','Today'],['team','Team'],['onb','Onboarding',D.joiners.filter(j=>j.step<4).length],['leave','Leave',D.leave.filter(l=>l.st==='Pending').length],['exit','Exits',D.exits.length],['rules','Rules']],t,'ptab')+'<div style="margin-top:12px"></div>';
 if(t==='today')return head+`<div class="stats">${['In','Late','Leave','Not in'].map(s=>`<div><b>${D.att.filter(a=>a.st===s).length}</b><span>${s}</span></div>`).join('')}</div><div class="list">${D.att.map(a=>`<button class="li" data-a="person" data-k="${a.k}">${av(nm(a.k))}<div class="tx"><b>${h(nm(a.k))}</b><div class="m">${a.in||'—'}${a.gps?' · '+h(a.gps):''}</div></div>${pill(a.st,{In:'g',Late:'a',Leave:'b','Not in':'r'}[a.st]||'')}</button>`).join('')}</div>`;
 if(t==='team'){const teams=[...new Set(STAFF.map(k=>P[k].team))];return head+teams.map(tm=>`<div class="list"><div class="grp">${h(tm)}</div>${STAFF.filter(k=>P[k].team===tm).map(k=>{const r=kpiRows().find(x=>x.k===k);return `<div class="li"><button class="tx row nw" data-a="person" data-k="${k}" style="border:0;background:none;text-align:left;padding:0;gap:12px;flex:1">${av(P[k].n)}<div><b>${h(P[k].n)}</b><div class="m">${h(P[k].r)} · ${staffId(k)}</div></div></button>${r?pill('★ '+r.s,r.s>=75?'g':r.s>=55?'a':'r'):''}${iBtn('staffLogin',`data-k="${k}"`)}</div>`}).join('')}</div>`).join('')+'<div class="note">Tap <b>i</b> next to anyone to see their login ID (mobile + OTP), employee ID and device lock.</div>'}
 if(t==='onb'){const ST=['Link sent','Details filled','Documents verified','Policies signed','Active'];return head+(D.joiners.map((j,i)=>`<div class="card"><div class="row nw">${av(j.n)}<div style="flex:1"><b style="font-size:16px">${h(j.n)}</b><div class="xs mut">${h(j.desig)} · ${h(BOOKS[j.co]||j.co)} · ${h(j.team)} · reports to ${h(nmF(j.lead))} · joins ${fmt(j.doj)}</div><div class="xs" style="margin-top:3px">🔑 Login: <b>${h(j.mob)}</b> · OTP · ID JDAC-${CODE[j.co]||'JS'}-0${20+i}</div></div></div>${trk(ST,j.step)}${j.step<4?`<button class="btn sm" style="margin-top:6px" data-a="onbStep" data-i="${i}">Mark “${ST[j.step]}” done</button>`:pill('Active · login on','g')}</div>`).join('')||`<div class="list">${empty('No joiners right now')}</div>`)+`<div class="note">Nameera creates the login and sends a link. The joiner fills bank, PAN, birth date, emergency contacts, signs the offer letter & HR policies and adds a photo. Only Nameera and Darshan can see documents.</div>`}
 if(t==='leave')return head+`<button class="btn sec w" data-a="leaveNew" style="margin-bottom:12px">Apply leave for someone</button><div class="list">${D.leave.map((l,i)=>`<div class="li">${av(nm(l.k))}<div class="tx"><b>${h(nm(l.k))} · ${fmt(l.from)}${l.to!==l.from?' – '+fmt(l.to):''}</b><div class="m">${h(l.why)} · lead notified</div></div>${l.st==='Pending'&&isAdm()?`<button class="btn sm g" data-a="lvOk" data-i="${i}">Approve</button><button class="btn sm sec" data-a="lvNo" data-i="${i}">No</button>`:pill(l.st,l.st==='Approved'?'g':l.st==='Rejected'?'r':'a')}</div>`).join('')}</div>`;
 if(t==='exit')return head+(D.exits.map(x=>`<div class="card"><div class="row nw">${av(nm(x.k))}<div style="flex:1"><b>${h(nm(x.k))}</b><div class="xs mut">Last day ${fmt(x.last)} · ${h(x.why)} · work to ${h(nmF(x.to))}</div></div></div>${trk(['Work reassigned','Handover tasks','Assets returned','Settlement accepted','Login closed'],x.step)}${x.step<5?`<button class="btn sm" style="margin-top:6px" data-a="exStep" data-k="${x.k}">Next step</button>`:''}</div>`).join('')||`<div class="list">${empty('No exits','Start one from a person\'s profile')}</div>`)+`<div class="note">Notice 30 days (3 months for key people like Nameera, Om Parvate, Swapnil). Leaving without notice forfeits pending salary. All assets must be returned before settlement.</div>`;
 return head+`<div class="list">${[['Late after 10:10 am · 3 lates = half day','clock'],['Missed clock-out closes at midnight · 3 misses = half day','clock'],['Office clock-in within ~200 m of KPCT Mall · work from home = half day','pin'],['Leave 3 days ahead · no Saturday/Monday sandwich leave','cal'],['2 unapproved absences unpaid · from the 3rd, one extra day cut','user'],['Sunday off (office) · rotational off (warehouse, open 365 days)','cal'],['10–11 holidays a year, state-wise · Goa also gets 19 Dec','cal'],['TA ₹3/km on own vehicle after approval · Atmaram ₹100/day DA · no overtime','truck'],['Staff see a limited pay breakup; salary slips on request','doc']].map(r=>`<div class="li"><div class="av" style="background:var(--bg);color:var(--navy);border-radius:12px">${ic(r[1])}</div><div class="tx"><b style="font-weight:500">${r[0]}</b></div></div>`).join('')}</div>`};
V.person=()=>{const k=S.pk||'neetu',p=P[k];if(!p)return V.people();const a=D.att.find(x=>x.k===k)||{},r=kpiRows().find(x=>x.k===k),T=D.tasks.filter(t=>t.o===k),open=T.filter(t=>t.st!=='Done'),tg=D.targets.filter(t=>t.who===k),led=D.ledger.filter(l=>l.k===k);
 const pres=seedNum(k,17,22),late=seedNum(k,0,3);
 return back('people','HR Desk')+`<div class="card"><div class="row nw">${av(p.n,'l')}<div style="flex:1"><h2>${h(p.n)}</h2><div class="mut sm">${h(p.r)} · ${h(p.team)}</div><div class="xs mut">${staffId(k)} · login ${staffMob(k)}</div></div>${isAdm()?iBtn('staffLogin',`data-k="${k}"`):''}${r?`<div style="text-align:center"><div class="ring" style="background:conic-gradient(${r.s>=75?'var(--g)':r.s>=55?'var(--o)':'var(--r)'} ${r.s*3.6}deg,#ECEDF0 0)"><span>${r.s}</span></div><div class="xs mut">KPI</div></div>`:''}</div>
 <div class="row" style="margin-top:12px"><span class="pill ${a.st==='In'?'g':a.st==='Late'?'a':''}">Today: ${h(a.st||'—')}${a.in?' · '+a.in:''}</span>${a.gps?pill(a.gps,'t'):''}</div></div>
 ${st('This month')}<div class="stats"><div><b>${pres}/22</b><span>days present</span></div><div><b style="color:${late>=3?'var(--r)':'inherit'}">${late}/3</b><span>late marks</span></div><div><b>${r?r.tsk:'—'}%</b><span>tasks on time</span></div><div><b style="color:var(--g)">${inr(led.reduce((s,l)=>s+l.amt,0))}</b><span>incentives</span></div></div>
 ${tg.length?`${st('Targets')}<div class="list">${tg.map(t=>{const pp=pct(t.v,t.goal);return `<div class="ms">${ring(pp)}<div class="tx"><b>${h(t.l)}</b><div class="xs mut">per ${t.per}</div></div><b class="num">${t.unit==='₹'?inr(t.v):t.v}/${t.unit==='₹'?inr(t.goal):t.goal}</b></div>`}).join('')}</div>`:''}
 ${r?`<div class="card"><b>Insight</b><div class="sm mut" style="margin-top:4px">${r.s>=75?'On track — numbers and tasks both strong. Consider a shout-out in Announcements.':'Needs a nudge: '+h(r.why)+'. Suggested: a 1-minute training item and a check-in today.'}</div></div>`:''}
 ${st('Open tasks',`<button class="lnk" data-a="tNewFor" data-k="${k}">+ Assign</button>`)}<div class="list">${open.map(taskRow).join('')||empty('No open tasks')}</div>
 ${st('Records')}<div class="list"><div class="li"><div class="tx"><b>Documents</b><div class="m">Aadhaar, PAN, bank, offer letter, policies</div></div>${pill('Verified','g')}</div><div class="li"><div class="tx"><b>Assets</b><div class="m">${D.assets.filter(x=>x.k===k).map(x=>h(x.a)).join(', ')||'None'}</div></div></div><div class="li"><div class="tx"><b>Notice period</b><div class="m">${['nameera','omparvate','swapnil'].includes(k)?'3 months':'30 days'}</div></div></div></div>
 ${isAdm()&&!D.exits.some(x=>x.k===k)?`<button class="btn sec w" data-a="exNew" data-k="${k}">Start exit</button>`:''}`};

