A.tStep=e=>{const t=D.targets.find(x=>x.id===e.dataset.id);if(!['darshan','nameera'].includes(S.me)&&t.who!==S.me)return toast('Only the owner updates this number');t.v=Math.max(0,t.v+(+e.dataset.n)*(t.unit==='₹'?1000:1));save();render()};
A.tEdit=()=>sheet(`<h2>Edit targets</h2><p class="mut sm">Only Darshan and Nameera can change targets.</p>${D.targets.map(t=>`<div class="row nw" style="margin-top:10px"><label for="tg-${t.id}" style="flex:1;margin:0;color:var(--ink);font-weight:500">${h(t.l)}</label><input id="tg-${t.id}" type="number" value="${t.goal}" style="width:100px"><select id="tp-${t.id}" style="width:auto" aria-label="Per"><option ${t.per==='day'?'selected':''}>day</option><option ${t.per==='week'?'selected':''}>week</option></select></div>`).join('')}<button class="btn w" style="margin-top:16px" data-a="tSave">Save</button>`);
A.tSave=()=>{D.targets.forEach(t=>{t.goal=+val('tg-'+t.id)||t.goal;t.per=val('tp-'+t.id)||t.per});save();closeM();render();toast('Targets saved')};
/* tasks */
function nextStep(t){if(blocked(t))return [null,'Waiting for the earlier step'];if(t.st==='Done')return [null,'Done'];if(t.st==='Review')return canApprove(t)?['Done','Approve ✓']:[null,'Waiting for '+nmF(t.by||'darshan')+' to approve'];if(t.st==='Working')return ['Review','Send for approval'];return ['Working','Start task']}
A.tQuick=e=>{const t=D.tasks.find(x=>x.id===e.dataset.id),[n,l]=nextStep(t);if(!n)return toast(l);setSt(t,n)};
function setSt(t,n){t.st=n;if(n==='Done')D.tasks.filter(x=>x.dep===t.id&&x.st==='Planning').forEach(x=>x.st='To do');save();closeM();render();toast(n==='Done'?'Approved ✓ next step unlocked':n==='Review'?'Sent to '+nmF(t.by||'darshan')+' for approval':n==='Stuck'?'Marked stuck · giver notified':'Started')}
A.tOpen=e=>{const t=D.tasks.find(x=>x.id===e.dataset.id),[n,l]=nextStep(t),cur=t.st==='Done'?4:Math.max(0,TFLOW.indexOf(['Planning','Stuck'].includes(t.st)?'To do':t.st));
 sheet(`<div class="row" style="gap:6px">${pill(CO[t.co]?.n||'')}${t.pri==='High'?pill('High priority','r'):''}${t.type!=='One-time'?pill(t.type,'t'):''}${t.g?pill('Goal step','p'):''}${t.st==='Stuck'?pill('Stuck','r'):''}</div><h2 style="margin-top:10px">${h(t.t)}</h2>
 <div class="row nw" style="margin-top:10px">${av(nm(t.o))}<div class="sm"><b>${h(nm(t.o))}</b><div class="mut">given by ${h(nm(t.by||'darshan'))} · due ${fmtY(t.due)}${t.st!=='Done'&&t.due<TODAY?` · <b style="color:var(--r)">late</b>`:''}</div></div></div>
 ${trk(['To do','Working','Approval','Done'],cur)}
 ${t.desc?`<p class="sm" style="background:var(--bg);border-radius:12px;padding:10px 12px">${h(t.desc)}</p>`:''}
 ${t.target?`<div class="row"><span class="pill o">Target: ${h(t.target)}</span></div>`:''}
 ${(t.check||[]).length?`<label>Checklist</label>${t.check.map((c,i)=>`<label class="row nw" style="margin:0;padding:8px 0;border-top:1px solid var(--line);color:var(--ink);font-weight:500"><input type="checkbox" data-ch="tck" data-id="${t.id}" data-i="${i}" ${c.d?'checked':''} style="width:20px;min-height:20px"> ${h(c.t)}</label>`).join('')}`:''}
 ${(t.tags||[]).length?`<div style="margin-top:8px">${t.tags.map(x=>`<span class="tag">${h(x)}</span>`).join('')}</div>`:''}
 <label for="tpr">Proof · file, Drive or Instagram link</label><input id="tpr" value="${h(t.proof||'')}" placeholder="https://drive.google.com/…">
 <div class="row" style="margin-top:16px">${n?`<button class="btn" style="flex:1" data-a="tGo" data-id="${t.id}" data-n="${n}">${l}</button>`:`<div class="pill" style="flex:1;justify-content:center;min-height:46px">${h(l)}</div>`}${t.st!=='Done'&&t.st!=='Stuck'&&!blocked(t)?`<button class="btn sec" data-a="tGo" data-id="${t.id}" data-n="Stuck">Stuck</button>`:''}</div>`)};
A.tGo=e=>{const t=D.tasks.find(x=>x.id===e.dataset.id);t.proof=val('tpr');setSt(t,e.dataset.n)};
function assignable(){if(isAdm()||K()==='acc')return STAFF;const tm=ME().team;return STAFF.filter(k=>P[k].team===tm||['nameera','snehalz'].includes(k))}
function taskForm(d){d=d||{};const who=assignable(),o=d.o&&who.includes(d.o)?d.o:who[0],due=d.due||addD(TODAY,1);
 return `<label for="nt">What needs to be done?</label><input id="nt" value="${h(d.t||'')}" placeholder="e.g. 3 Christmas reels"><label for="nd">Description · expected result</label><textarea id="nd" placeholder="e.g. 3 reels, 20–30 sec each">${h(d.desc||'')}</textarea>
 <label>Who?</label>${opts('nwho',who.map(k=>[k,nmF(k)]),o)}<input type="hidden" id="no" value="${o}">
 <label>When?</label>${opts('ndue',[[TODAY,'Today'],[addD(TODAY,1),'Tomorrow'],[addD(TODAY,3),'In 3 days'],[addD(TODAY,7),'Next week']],due)}<input id="ndu" type="date" value="${due}" style="margin-top:8px" aria-label="Due date">
 <div class="grid g2"><div><label for="nc">Company</label><select id="nc">${COK.map(k=>`<option value="${k}" ${d.co===k?'selected':''}>${CO[k].n}</option>`).join('')}</select></div><div><label for="nty">Repeat</label><select id="nty"><option>One-time</option><option>Daily</option><option>Weekly</option></select></div></div>
 <label for="nck">Checklist (one per line, optional)</label><textarea id="nck" style="min-height:64px" placeholder="Static 1&#10;Static 2&#10;Reel 1"></textarea>
 <div class="grid g2"><div><label for="ntg">Tags</label><input id="ntg" placeholder="Video, Meta"></div><div><label for="ntr">Number / revenue target</label><input id="ntr" placeholder="e.g. 50 orders"></div></div>
 <label for="nlk">Reference link (Drive, brief)</label><input id="nlk" placeholder="https://"><label class="btn sec w" style="margin-top:8px;cursor:pointer">${ic('up')}Attach image / file<input type="file" class="sr"></label>
 <label class="row nw" style="color:var(--ink);font-weight:600"><input type="checkbox" id="np" style="width:20px;min-height:20px" ${d.pri==='High'?'checked':''}> High priority</label>
 <button class="btn w" style="margin-top:14px" data-a="tCreate" ${d.m!=null?`data-m="${d.m}" data-i="${d.i}"`:''}>Assign task</button>`}
A.tNew=()=>sheet(`<h2>New task</h2>${taskForm()}`);
A.tNewFor=e=>sheet(`<h2>New task</h2>${taskForm({o:e.dataset.k})}`);
A.tCreate=e=>{if(!val('nt'))return toast('Write the task');const o=val('no'),id=nid('k');D.tasks.push({id,t:val('nt'),desc:val('nd')+(val('nlk')?' · '+val('nlk'):''),o,co:val('nc'),due:val('ndu'),pri:document.getElementById('np').checked?'High':'Normal',type:val('nty'),tags:val('ntg').split(',').map(s=>s.trim()).filter(Boolean),target:val('ntr'),check:val('nck').split('\n').map(s=>s.trim()).filter(Boolean).map(t=>({t,d:false})),st:'To do',by:S.me});
 if(e.dataset.m){const m=D.meet.find(x=>x.id===e.dataset.m);if(m)m.acts[+e.dataset.i].k=id}save();closeM();render();toast('Assigned to '+nmF(o))};
let REC=null;
A.voice=()=>sheet(`<h2>Speak a task</h2><p class="mut sm">e.g. “Swapnil, Christmas ke liye 3 reels Friday tak”. You check the draft before it goes out.</p><button class="btn w" data-a="recGo" style="min-height:64px;font-size:17px">${ic('mic')}<span id="recs">Tap and speak</span></button><label for="vtx">Or type it</label><textarea id="vtx"></textarea><button class="btn sec w" style="margin-top:10px" data-a="vDraft">Make draft</button><div id="vdraft"></div>`);
A.recGo=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Voice not available here — type instead');try{REC=new SR();REC.lang='hi-IN';REC.interimResults=true;REC.onresult=ev=>{document.getElementById('vtx').value=[...ev.results].map(r=>r[0].transcript).join(' ')};REC.onend=()=>A.vDraft();REC.start();document.getElementById('recs').textContent='Listening…'}catch(x){toast('Microphone not available')}};
A.vDraft=()=>{const t=val('vtx');if(!t)return;const low=t.toLowerCase();const o=STAFF.find(k=>low.includes(P[k].n.toLowerCase().split(' ')[0]))||assignable()[0];let co='log';if(/govaa|choco|christmas|retail/.test(low))co='gb';else if(/jupiter|bed|oxygen/.test(low))co='jup';else if(/hiring|candidate/.test(low))co='hr';else if(/reel|video|post|bahiram/.test(low))co='studios';
 const wd=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'].findIndex(d=>low.includes(d));let due=addD(TODAY,1);if(wd>=0)due=addD(TODAY,((wd-new Date().getDay()+7)%7)||7);if(/aaj|today/.test(low))due=TODAY;
 document.getElementById('vdraft').innerHTML=`<div style="border-top:1px solid var(--line);margin-top:16px;padding-top:6px"><h3>Draft — check it</h3>${taskForm({t:t.replace(/^\s*\w+[,:]\s*/,'').slice(0,90),o,co,due})}</div>`};
A.meetTask=e=>{const m=D.meet.find(x=>x.id===e.dataset.m),a=m.acts[+e.dataset.i];sheet(`<h2>Make task</h2>${taskForm({t:a.t,o:a.o,co:'log',m:m.id,i:e.dataset.i})}`)};
A.meetNew=()=>sheet(`<h2>Meeting notes</h2><label for="mt">Meeting</label><input id="mt" value="Genmak daily · jdac.in & IT"><label for="mn">Notes (paste, type or dictate)</label><textarea id="mn" style="min-height:120px" placeholder="One action per line, e.g. Himanshu: fix booking form"></textarea><p class="xs mut">Each line becomes an action item. Start a line with a name to assign it.</p><button class="btn w" data-a="meetSave">Save notes</button>`);
A.meetSave=()=>{const lines=val('mn').split('\n').map(s=>s.trim()).filter(Boolean);if(!lines.length)return toast('Add notes');D.meet.unshift({id:nid('M'),t:val('mt'),when:'Notes',with:[S.me],dt:TODAY,notes:lines.join(' '),acts:lines.map(l=>{const k=Object.keys(P).find(x=>l.toLowerCase().startsWith(P[x].n.toLowerCase().split(' ')[0]));return {t:l.replace(/^[^:]+:\s*/,''),o:k||'himanshu',k:null}})});save();closeM();render();toast('Saved · make tasks from the action items')};
/* content */
A.pNext=e=>{const p=D.posts.find(x=>x.id===e.dataset.id),i=CST.indexOf(p.st);if(p.st==='Edit')return sheet(`<h2>Mark posted</h2><p class="mut sm">${h(p.t)}</p>${p.plats.map(x=>`<label for="pl-${PLAT[x]}">${h(x)} link</label><input id="pl-${PLAT[x]}" placeholder="https://">`).join('')}<p class="xs mut">Posted outside the app? Paste each link — it goes to the Library and everyone tagged sees it.</p><button class="btn w" data-a="pPost" data-id="${p.id}">Mark posted ✓</button>`);p.st=CST[i+1];save();render();toast(p.t+' → '+p.st)};
A.pPost=e=>{const p=D.posts.find(x=>x.id===e.dataset.id);p.plats.forEach(x=>{p.links[x]=val('pl-'+PLAT[x])||'#'});p.st='Posted';p.plats.forEach(x=>D.lib.unshift({id:nid('C'),t:p.t,type:p.type==='Static'?'Static':'Video',co:p.co==='bah'?'studios':p.co,mode:'Organic',plat:x,by:S.me,tags:p.face,at:TODAY,link:p.links[x]}));save();closeM();render();toast('Posted on '+p.plats.length+' platform'+(p.plats.length>1?'s':'')+' ✓')};
A.pNew=()=>sheet(`<h2>Plan a post</h2>${postForm()}<button class="btn w" style="margin-top:16px" data-a="pCreate">Add to calendar</button>`);
A.pCreate=()=>{if(!val('pt'))return toast('Add a title');const pl=pickN('ppl');if(!pl.length)return toast('Pick at least one platform');D.posts.push({id:nid('P'),t:val('pt'),co:pick1('pco'),plats:pl,type:pick1('pty'),date:val('pdt'),time:val('ptm')||'19:30',st:'Script',face:pickN('pfa'),links:{}});S.cd=val('pdt');S.cv='day';save();closeM();render();toast('Added · '+pl.join(' + '))};
A.pOpen=e=>{const p=D.posts.find(x=>x.id===e.dataset.id);sheet(`<div class="row" style="gap:6px">${pill(BR[p.co].n)}${p.series?pill(p.series+' · '+p.code,'o'):''}</div><h2 style="margin-top:8px">${h(p.t)}</h2><p class="mut sm">${p.plats.join(' + ')} · ${h(p.type)} · ${fmtY(p.date)} · ${tm12(p.time)}</p>${trk(CST,p.st==='Posted'?4:CST.indexOf(p.st))}${Object.keys(p.links).length?`<div>${Object.keys(p.links).map(x=>pill(x+' ✓','g')).join(' ')}</div>`:''}${canEditPost()?postForm(p)+`<button class="btn w" style="margin-top:14px" data-a="pSave" data-id="${p.id}">Save</button>`:''}`)};
A.pSave=e=>{const p=D.posts.find(x=>x.id===e.dataset.id),pl=pickN('ppl');if(!pl.length)return toast('Pick at least one platform');Object.assign(p,{t:val('pt')||p.t,co:pick1('pco'),plats:pl,type:pick1('pty'),face:pickN('pfa'),date:val('pdt')||p.date,time:val('ptm')||p.time});save();closeM();render();toast('Saved')};
A.libNew=()=>sheet(`<h2>Add to Library</h2><label for="lt2">Title</label><input id="lt2"><label>Company</label>${opts('lco',Object.keys(CO).map(k=>[k,coShort(k)]),'log')}<label>Type</label>${opts('lty',['Video','Static','Ad creative','Landing page'],'Video')}<label>Paid or organic</label>${opts('lmd',['Organic','Paid'],'Organic')}<label>Platform</label>${opts('lpl',Object.keys(PLAT),'Instagram')}<label for="ll">Google Drive or live link</label><input id="ll" placeholder="https://"><label>Tag people</label>${opts('ltg',STAFF.map(k=>[k,nmF(k)]),[],true)}<button class="btn w" style="margin-top:16px" data-a="libSave">Add</button>`);
