/* gb */
let CART={};
A.punch=()=>{CART={r:'',items:{},rates:{},note:''};punchSheet()};
function punchSheet(){const n=Object.values(CART.items).reduce((a,b)=>a+b,0),rt=p=>CART.rates[p]!=null?CART.rates[p]:prd(p).rate,tot=Object.entries(CART.items).reduce((a,[p,q])=>a+q*rt(p),0);const r=D.retail.find(x=>x.id===CART.r),blk=r&&r.out&&-daysTo(r.since)>30,loss=Object.keys(CART.items).some(p=>rt(p)<prd(p).cost);
 sheet(`<h2>New order</h2><label for="pcr">Shop</label><select id="pcr" data-ch="pcr"><option value="">Choose shop…</option>${D.retail.map(x=>`<option value="${x.id}" ${CART.r===x.id?'selected':''}>${h(x.n)} · ${h(x.city)}</option>`).join('')}</select><button class="lnk" data-a="retNew">+ New shop</button>
 ${blk?`<div class="note" style="border-color:var(--r);color:var(--r)">Bill older than 1 month — you can punch, but delivery waits for payment.</div>`:r&&r.out?`<div class="note">Due: ${inr(r.out)}</div>`:''}
 <div>${D.prod.map(p=>{const q=CART.items[p.id]||0,avl=D.inv.goa[p.id]-reserved('goa',p.id);return `<div class="dish"><div style="flex:1"><b>${h(p.n)}</b><div class="row nw" style="gap:6px;margin:4px 0"><span class="sm mut">₹</span><input type="number" value="${rt(p.id)}" data-ch="pcrate" data-p="${p.id}" style="width:90px;min-height:34px;padding:4px 8px;font-weight:700" aria-label="Rate for ${h(p.n)}"></div><div class="xs mut">${avl} in Goa · ${avl<=0?'Nashik will ship':''}</div></div><div class="ph">GOVAA${q?`<div class="qty"><button data-a="pcq" data-p="${p.id}" data-n="-1" aria-label="Less">−</button><span>${q}</span><button data-a="pcq" data-p="${p.id}" data-n="1" aria-label="More">+</button></div>`:`<button class="add" data-a="pcq" data-p="${p.id}" data-n="1">ADD</button>`}</div></div>`}).join('')}</div>
 ${loss?`<div class="note" style="color:var(--r)">A rate is below cost — this shows as a loss in Accounts.</div>`:''}
 <label for="pcn">Offer / note</label><input id="pcn" data-ch="pcn" value="${h(CART.note)}" placeholder="e.g. 10 + 1 free">
 ${n?`<div class="cart"><div><b>${n} item${n>1?'s':''} · ${inr(tot)}</b><div class="xs" style="opacity:.85">Stock held on save · GST invoice auto</div></div><span class="sp"></span><button data-a="pcSave">Place order →</button></div>`:''}`)}
A.pcq=e=>{const p=e.dataset.p,n=+e.dataset.n,cur=CART.items[p]||0;if(n>0&&cur+1>D.inv.goa[p]-reserved('goa',p)+D.inv.nashik[p]-reserved('nashik',p))return toast('Not enough stock anywhere');const q=cur+n;if(q<=0)delete CART.items[p];else CART.items[p]=q;punchSheet()};
A.pcSave=()=>{if(!CART.r)return toast('Choose a shop first');const goaOk=Object.entries(CART.items).every(([p,q])=>D.inv.goa[p]-reserved('goa',p)>=q);const rt=p=>CART.rates[p]!=null?CART.rates[p]:prd(p).rate,tot=Object.entries(CART.items).reduce((a,[p,q])=>a+q*rt(p),0),loss=Object.keys(CART.items).some(p=>rt(p)<prd(p).cost),no='GB-'+(1045+D.gbo.length);
 D.gbo.push({id:no,r:CART.r,src:S.me==='atmaram'?'Atmaram':'Admin',wh:goaOk?'goa':'nashik',items:CART.items,rates:CART.rates,note:CART.note,loss,st:'Punched',pay:'',at:TODAY});D.targets.find(x=>x.id==='t5').v+=tot;addV({ty:'Sale',co:'gb',party:rName(CART.r),amt:tot,gst:18,mode:'Credit',by:'System',st:'Verified',src:'Order '+no+(loss?' · below cost':''),paid:0});save();closeM();render();toast(no+' placed · '+inr(tot)+(goaOk?'':' · ships from Nashik'))};
