A.grnNew=()=>sheet(`<h2>Goods arrived (GRN)</h2><label for="gf">From</label><input id="gf" value="Prakash Foods · Nashik"><label for="gi">What came?</label><textarea id="gi" placeholder="e.g. Dark Choconut × 300"></textarea><label for="ga">Bill amount ₹</label><input id="ga" type="number" inputmode="decimal"><label class="btn sec w" style="margin-top:10px;cursor:pointer">${ic('cam')}Photo of supplier bill<input type="file" accept="image/*" class="sr" data-ch="gotfile" data-t="grn"></label><div class="xs mut" id="grn-f">No photo yet</div><button class="btn w" style="margin-top:14px" data-a="grnSave">Save · stock goes up</button>`);
