A.expNew=()=>{const co=ME().team==='Warehouse'||S.me==='zubair'?'jup':S.me==='atmaram'?'gb':'log';sheet(`<h2>Add expense</h2><label for="ea">Amount ₹</label><input id="ea" type="number" inputmode="decimal"><label>What for?</label>${opts('eh',['Delivery travel','Labour','Fuel','Office','Food','Repair','Other'],'Delivery travel')}<label for="ep">Paid to</label><input id="ep" placeholder="e.g. Rapido, labour, petrol pump"><label>Paid by</label>${opts('em',['Cash','UPI','Company card','Porter wallet'],'Cash')}<label class="btn sec w" style="margin-top:10px;cursor:pointer">${ic('cam')}Bill / QR photo<input type="file" accept="image/*" class="sr" data-ch="gotfile" data-t="exp"></label><div class="xs mut" id="exp-f">No photo yet</div><input type="hidden" id="eco" value="${co}"><p class="xs mut">${co==='jup'?'Zubair approves first, then Snehal Z or Nameera pays from Pune petty cash.':'Goes to Snehal Z to verify.'}</p><button class="btn w" data-a="expSave">Submit</button>`)};
