/* accounts */
const VFIELDS={Sale:'Customer',Receipt:'Received from',Purchase:'Supplier',Expense:'Paid to','Credit note':'Customer','Debit note':'Supplier','Cash deposit':'From cash account',Journal:'Description'};
A.vNew=()=>{sheet(`<h2>New entry</h2><label>Type</label>${opts('vty',Object.keys(VTY),'Expense')}<div id="vform"></div>`);vFormFill()};
function vFormFill(){const ty=pick1('vty')||'Expense',f=document.getElementById('vform');if(!f)return;const accts=D.banks.map(b=>[b.id,b.n+' '+b.no]).concat(D.petty.map(p=>['c-'+p.id,'Cash · '+p.n]));
 f.innerHTML=`<label>Company books</label>${opts('vco',Object.keys(BOOKS).map(k=>[k,coShort(k)]),S.mbk||'gb')}<label for="vp">${VFIELDS[ty]}</label><input id="vp" list="parties"><datalist id="parties">${[...new Set(D.vch.map(v=>v.party))].map(p=>`<option value="${h(p)}">`).join('')}</datalist>
 <div class="grid g2"><div><label for="va">Amount ₹ (incl. GST)</label><input id="va" type="number" inputmode="decimal"></div><div><label for="vd">Date</label><input id="vd" type="date" value="${TODAY}"></div></div>
 ${['Sale','Purchase','Expense','Credit note','Debit note'].includes(ty)?`<label>GST rate</label>${opts('vg',['0','5','12','18','28'],'18')}`:''}
 ${ty!=='Journal'?`<label>Mode</label>${opts('vm',['Cash','UPI','Bank','Cheque','Credit'],ty==='Sale'||ty==='Purchase'?'Credit':'UPI')}<label for="vac">Bank / cash account</label><select id="vac"><option value="">—</option>${accts.map(a=>`<option value="${a[0]}">${h(a[1])}</option>`).join('')}</select>`:''}
 ${ty==='Expense'?`<label>Expense head</label>${opts('vh',['Delivery travel','Labour','Fuel','Office','Rent','Salaries','Marketing','Other'],'Office')}`:''}
 <label for="vn">Note / bill no.</label><input id="vn"><label class="btn sec w" style="margin-top:10px;cursor:pointer">${ic('up')}Attach bill<input type="file" class="sr" data-ch="gotfile" data-t="vb"></label><div class="xs mut" id="vb-f">No file</div><button class="btn w" style="margin-top:14px" data-a="vSave">${isAcc()?'Save entry':'Submit for verification'}</button>`}
A.vSave=()=>{const a=+val('va'),p=val('vp');if(!a||!p)return toast('Party and amount are needed');const ty=pick1('vty');const v=addV({ty,co:pick1('vco'),party:p,amt:a,dt:val('vd'),gst:+(pick1('vg')||0),mode:pick1('vm')||'—',acct:val('vac'),src:val('vn')||'Manual entry',head:pick1('vh'),paid:ty==='Sale'&&pick1('vm')!=='Credit'?a:0,file:document.getElementById('vb-f').textContent!=='No file'?1:0});logA(`${ty} entry · ${p} · ${inr(a)}`);save();closeM();render();toast(v.st==='Verified'?'Saved to the books':'Sent for verification')};
A.vOpen=e=>{const v=D.vch.find(x=>x.id===e.dataset.id);if(!v)return;sheet(`<div class="row" style="gap:6px">${pill(v.ty,(VTY[v.ty]||[''])[0])}${pill(v.st,v.st==='Verified'?'g':v.st==='Split needed'?'r':'a')}</div><h2 style="margin-top:8px">${h(v.party)}</h2><div class="num" style="font-size:30px;font-weight:800;margin:4px 0">${inr(v.amt)}</div>
 <div class="list">${[['Company',BOOKS[v.co]],['Date',fmtY(v.dt)],['GST',v.gst?v.gst+'% · '+inr(gstOf(v)):'—'],['Mode',v.mode],['Account',acctName(v.acct)],['Expense head',v.head||''],['Entered by',v.by==='System'?'Automatic':nm(v.by)],['Source',v.src],['Bill / photo',v.file?'Attached 📎':'—'],...(v.ty==='Sale'?[['Received',inr(v.paid||0)+' of '+inr(v.amt)]]:[])].filter(r=>r[1]).map(r=>`<div class="li"><div class="tx"><div class="m">${r[0]}</div><b style="font-weight:600">${h(r[1])}</b></div></div>`).join('')}</div>
 ${isAcc()&&v.st!=='Verified'?`<div class="row">${v.st==='Split needed'?`<button class="btn" style="flex:1" data-a="vSplit" data-id="${v.id}">Split</button>`:`<button class="btn g" style="flex:1" data-a="vOk" data-id="${v.id}">Verify</button>`}<button class="btn sec" data-a="vNo" data-id="${v.id}">Reject</button></div>`:''}`)};
A.vOk=e=>{const v=D.vch.find(x=>x.id===e.dataset.id);v.st='Verified';if(v.ref){const s=D.vch.find(x=>x.id===v.ref);if(s)s.paid=Math.min(s.amt,(s.paid||0)+v.amt)}if(v.src&&v.src.startsWith('GRN')){const g=D.grn.find(x=>x.id===v.src);if(g)g.st='Verified'}const pay=D.pays&&D.pays.find(p=>p.what&&v.src&&p.what.includes(v.src.split(' ').pop()));if(pay)pay.st='Verified';logA(`Verified ${v.ty} · ${v.party} · ${inr(v.amt)}`);save();closeM();render();toast('Verified · balances updated')};
A.vNo=e=>{const v=D.vch.find(x=>x.id===e.dataset.id);v.st='Rejected';logA(`Rejected ${v.ty} · ${v.party}`);save();closeM();render();toast('Rejected · sent back to '+nmF(v.by))};
A.vSplit=e=>{const v=D.vch.find(x=>x.id===e.dataset.id);sheet(`<h2>Split payment</h2><p class="mut sm">${h(v.party)} paid ${inr(v.amt)} on Jupiter's QR.</p><div class="grid g2"><div><label for="sp1">Rent → Jupiter</label><input id="sp1" type="number" value="${v.amt-1800}"></div><div><label for="sp2">Transport → JDAC</label><input id="sp2" type="number" value="1800"></div></div><p class="xs mut">The transport part is added to the month-end settlement as money Jupiter owes JDAC.</p><button class="btn w" data-a="vSplitSave" data-id="${v.id}">Save split</button>`)};
A.vSplitSave=e=>{const v=D.vch.find(x=>x.id===e.dataset.id),t=+val('sp2');v.st='Verified';v.amt=t;v.party=v.party+' · transport share';addV({ty:'Journal',co:'jup',party:'Jupiter owes JDAC (transport on QR)',amt:t,st:'Verified',src:'Split of '+v.id,mode:'—'});logA('Split Jupiter QR payment');save();closeM();render();toast('Split saved · added to settlement')};
A.bankOpen=e=>{S.v='money';S.mtab='bank';S.bk=e.dataset.id;render();scrollTo(0,0)};
A.bankX=()=>{S.bk=null;render()};
A.lineMatch=e=>{const L=D.stmt[e.dataset.b][+e.dataset.i];const cand=D.vch.filter(v=>v.amt===Math.abs(L.amt)&&!Object.values(D.stmt).flat().some(l=>l.m===v.id));sheet(`<h2>Match bank line</h2><p class="mut sm">${h(L.desc)} · ${fmt(L.d)} · ${inr(Math.abs(L.amt))}</p>${cand.length?`<label>Suggested entries</label><div class="list">${cand.map(v=>`<button class="li" data-a="lineSet" data-b="${e.dataset.b}" data-i="${e.dataset.i}" data-v="${v.id}"><div class="tx"><b>${h(v.party)}</b><div class="m">${h(v.ty)} · ${fmt(v.dt)} · ${h(v.st)}</div></div><b class="amt">${inr(v.amt)}</b></button>`).join('')}</div>`:'<div class="note">No entry with this amount.</div>'}<button class="btn sec w" data-a="lineNew" data-b="${e.dataset.b}" data-i="${e.dataset.i}">Create a new entry from this line</button>`)};
A.lineSet=e=>{const L=D.stmt[e.dataset.b][+e.dataset.i];L.m=e.dataset.v;const v=D.vch.find(x=>x.id===e.dataset.v);if(v&&v.st!=='Verified'){v.st='Verified';v.acct=e.dataset.b}logA('Matched bank line '+L.desc);save();closeM();render();toast('Matched ✓')};
A.lineNew=e=>{const b=D.banks.find(x=>x.id===e.dataset.b),L=D.stmt[b.id][+e.dataset.i];const v=addV({ty:L.amt>0?'Receipt':'Expense',co:b.co,party:L.desc,amt:Math.abs(L.amt),mode:'Bank',acct:b.id,dt:L.d,src:'From bank statement',st:'Verified'});L.m=v.id;logA('Entry created from bank line '+L.desc);save();closeM();render();toast('Entry created and matched')};
A.ledger=e=>{const n=e.dataset.n,L=D.vch.filter(v=>v.party===n).sort((a,b)=>a.dt.localeCompare(b.dt));let bal=0;sheet(`<h2>${h(n)}</h2><p class="mut sm">Ledger · running balance</p><div class="list">${L.map(v=>{const s={Sale:1,Receipt:-1,'Credit note':-1,Purchase:-1,'Debit note':1}[v.ty]||0;bal+=s*v.amt;return `<button class="li" data-a="vOpen" data-id="${v.id}"><div class="tx"><b>${h(v.ty)}</b><div class="m">${fmt(v.dt)} · ${h(v.src)}</div></div><div style="text-align:right"><div class="amt">${s>0?'+':s<0?'−':''}${inr(v.amt)}</div><div class="xs mut">bal ${inr(Math.abs(bal))} ${bal>0?'Dr':bal<0?'Cr':''}</div></div></button>`}).join('')}</div>`)};
A.paySup=e=>{const v=D.vch.find(x=>x.id===e.dataset.id);sheet(`<h2>Pay ${h(v.party)}</h2><p class="mut sm">${inr(v.amt)} · ${h(v.src)}</p><label for="psa">From account</label><select id="psa">${D.banks.filter(b=>b.co===v.co||v.co==='jup').map(b=>`<option value="${b.id}">${h(b.n)} ${h(b.no)} · ${inr(bankBal(b))}</option>`).join('')}</select><button class="btn w" style="margin-top:14px" data-a="paySupSave" data-id="${v.id}">Record payment</button>`)};
A.paySupSave=e=>{const v=D.vch.find(x=>x.id===e.dataset.id);v.settled=true;addV({ty:'Expense',co:v.co,party:v.party,amt:v.amt,mode:'Bank',acct:val('psa'),src:'Payment for '+v.src,head:'Supplier payment',st:'Verified'});logA('Paid '+v.party+' '+inr(v.amt));save();closeM();render();toast('Payment recorded · bank updated')};
/* chat */
A.chatOpen=e=>{S.chat=e.dataset.id;render();const t=document.getElementById('thr');if(t)t.scrollTop=1e6};
A.chatX=()=>{S.chat=null;render()};
A.send=()=>{const t=val('msg');if(!t)return;D.msgs.push({g:S.chat,f:S.me,t,at:new Date().toTimeString().slice(0,5)});save();render();const th=document.getElementById('thr');if(th)th.scrollTop=1e6;const i=document.getElementById('msg');if(i)i.focus()};
A.grpNew=()=>sheet(`<h2>New group</h2><label for="gn">Group name</label><input id="gn" placeholder="e.g. CSE + Ops"><label>Members</label>${opts('gm',STAFF.map(k=>[k,nmF(k)]),['darshan','nameera'],true)}<button class="btn w" style="margin-top:14px" data-a="grpSave">Create</button>`);
A.grpSave=()=>{if(!val('gn'))return toast('Name the group');D.groups.push({id:nid('g'),n:val('gn'),m:pickN('gm')});save();closeM();render();toast('Group created')};
/* people */
A.lvOk=e=>{D.leave[+e.dataset.i].st='Approved';save();render();toast('Approved · team lead notified')};
A.lvNo=e=>{D.leave[+e.dataset.i].st='Rejected';save();render()};
A.leaveNew=()=>sheet(`<h2>Apply leave</h2>${isAdm()?`<label for="lk">For</label><select id="lk">${STAFF.map(k=>`<option value="${k}" ${k===S.me?'selected':''}>${h(P[k].n)}</option>`).join('')}</select>`:''}<div class="grid g2"><div><label for="lf">From</label><input id="lf" type="date" value="${addD(TODAY,3)}"></div><div><label for="lt">To</label><input id="lt" type="date" value="${addD(TODAY,3)}"></div></div><label for="lw">Reason</label><input id="lw"><p class="xs mut">At least 3 days ahead · no Saturday/Monday sandwich leave</p><button class="btn w" data-a="lvSave">Send to HR Manager Nameera</button>`);
A.lvSave=()=>{const f=val('lf'),t=val('lt');if(t<f)return toast('End date is before start');if(daysTo(f)<3)return toast('Apply at least 3 days ahead');for(let d=f;d<=t;d=addD(d,1)){const w=new Date(d+'T12:00:00').getDay();if(w===6||w===1)return toast('Saturday/Monday leave is blocked')}D.leave.push({k:val('lk')||S.me,from:f,to:t,why:val('lw')||'—',st:'Pending'});save();closeM();render();toast('Sent to Nameera')};
A.onbNew=()=>sheet(`<h2>Add joiner</h2><div class="grid g2"><div><label for="on">Full name *</label><input id="on"></div><div><label for="op">Mobile *</label><input id="op" inputmode="tel"></div></div>
 <label>Company *</label>${opts('oco',[...Object.keys(BOOKS).map(k=>[k,coShort(k)]),['parent','JDAC Sales (parent)']],'log')}
 <label>Team *</label>${opts('otm',TEAMS,'CSE')}<label for="od">Designation *</label><input id="od" placeholder="e.g. Customer Success Executive">
 <div class="grid g2"><div><label for="ol">Reports to</label><select id="ol">${STAFF.map(k=>`<option value="${k}">${h(P[k].n)}</option>`).join('')}</select></div><div><label for="oj">Joining date</label><input id="oj" type="date" value="${addD(TODAY,3)}"></div></div>
 <label>Work location</label>${opts('olc',['Pune office','Pune warehouse','Goa','Panvel','Nashik','Field'],'Pune office')}
 <div class="grid g2"><div><label for="os">Monthly salary ₹</label><input id="os" type="number"></div><div><label>Weekly off</label>${opts('oof',['Sunday','Rotational'],'Sunday')}</div></div>
 <label>Notice period</label>${opts('ont',['30 days','3 months'],'30 days')}<label>Live GPS tracking</label>${opts('ogp',['Check-in only','All day (field)'],'Check-in only')}
 <p class="xs mut">Creates the login + Employee ID and sends a link. They fill bank, PAN, birth date, emergency contacts, sign the offer letter & HR policies and add a photo. You verify.</p><button class="btn w" data-a="onbSave">Create login & send link</button>`);
A.onbSave=()=>{if(!val('on')||!val('op')||!val('od'))return toast('Name, mobile and designation are needed');D.joiners.unshift({n:val('on'),mob:val('op'),co:pick1('oco'),team:pick1('otm'),desig:val('od'),lead:val('ol'),loc:pick1('olc'),doj:val('oj'),sal:+val('os')||0,off:pick1('oof'),notice:pick1('ont'),gps:pick1('ogp'),step:1});S.ptab='onb';S.v='people';save();closeM();render();toast('Login created · link sent to '+val('on'))};
A.onbStep=e=>{const j=D.joiners[+e.dataset.i];j.step=Math.min(4,j.step+1);save();render();toast(j.step===4?j.n+' is active':'Updated')};
A.exNew=e=>{const k=e.dataset.k;sheet(`<h2>Start exit · ${h(nm(k))}</h2><label for="xl">Last working day</label><input id="xl" type="date" value="${addD(TODAY,['nameera','omparvate','swapnil'].includes(k)?90:30)}"><label>Reason</label>${opts('xr',['Resigned','Better offer','Performance','Absconded','Personal'],'Resigned')}<label for="xt">Hand over work to</label><select id="xt">${STAFF.filter(x=>x!==k).map(x=>`<option value="${x}">${h(P[x].n)}</option>`).join('')}</select><div class="note">${D.tasks.filter(t=>t.o===k&&t.st!=='Done').length} open tasks and ${D.assets.filter(a=>a.k===k).length} assets will be listed for handover. Leaving without notice forfeits pending salary.</div><button class="btn w" data-a="exSave" data-k="${k}">Start exit</button>`)};
A.exSave=e=>{const k=e.dataset.k;D.exits.push({k,last:val('xl'),why:pick1('xr'),to:val('xt'),step:0});save();closeM();S.ptab='exit';S.v='people';render();toast('Exit started')};
A.exStep=e=>{const x=D.exits.find(y=>y.k===e.dataset.k);x.step++;if(x.step===1)D.tasks.filter(t=>t.o===x.k&&t.st!=='Done').forEach(t=>t.o=x.to);save();render();toast(x.step===1?'Open tasks moved to '+nmF(x.to):x.step===5?'Login closed':'Updated')};
A.ledOk=e=>{D.ledger[+e.dataset.i].st='Approved · Nameera';save();render();toast('Approved · added to salary breakup')};
/* clock */
let STREAM=null;function stopCam(){if(STREAM){STREAM.getTracks().forEach(t=>t.stop());STREAM=null}}
A.clock=async()=>{const a=D.att.find(x=>x.k===S.me);if(a&&a.in&&!a.out){a.out=new Date().toTimeString().slice(0,5);save();render();return toast('Clocked out at '+a.out)}
 const w=document.getElementById('camwrap');if(!w){S.v='me';render();return}w.innerHTML=`<div style="margin-top:12px"><video id="vid" autoplay playsinline muted style="width:100%;max-width:300px;border-radius:16px;background:#000"></video><button class="btn w" style="margin-top:10px" data-a="snap">${ic('cam')}Take selfie & clock in</button><div class="xs mut" id="gps" style="margin-top:6px">Checking location…</div></div>`;
 try{STREAM=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'}});document.getElementById('vid').srcObject=STREAM}catch(x){const v=document.getElementById('vid');if(v)v.outerHTML='<div class="note">Camera opens in the real app (front camera only, no uploads).</div>'}
 try{navigator.geolocation.getCurrentPosition(p=>{const d=dist(p.coords.latitude,p.coords.longitude,18.4975,73.8983),g=document.getElementById('gps');if(g)g.textContent=(typeof empOf==='function'&&(empOf(S.me)||{}).anyLoc)?'Location stamped · allowed to mark from anywhere':d<=200?'Inside office area':'Away from office · counts as field / WFH'},()=>{const g=document.getElementById('gps');if(g)g.textContent='Turn location on to clock in'})}catch(x){}};
function dist(a,b,c,d){const R=6371e3,r=x=>x*Math.PI/180;const x=Math.sin(r(c-a)/2)**2+Math.cos(r(a))*Math.cos(r(c))*Math.sin(r(d-b)/2)**2;return 2*R*Math.asin(Math.sqrt(x))}
A.snap=()=>{stopCam();let a=D.att.find(x=>x.k===S.me);if(!a){a={k:S.me};D.att.push(a)}a.in=new Date().toTimeString().slice(0,5);a.out='';a.st=a.in>'10:10'?'Late':'In';a.gps=(document.getElementById('gps')||{}).textContent||'GPS stamped';save();render();toast('Clocked in '+a.in+(a.st==='Late'?' · late mark':''))};
A.trOpen=()=>{const t=D.training.today;sheet(`<span class="pill r">Compulsory</span><h2 style="margin-top:8px">${h(t.t)}</h2><p>${h(t.q)}</p>${t.opts.map((o,i)=>`<button class="btn sec w" style="margin-top:8px;justify-content:flex-start" data-a="trAns" data-i="${i}">${h(o)}</button>`).join('')}`)};
A.trAns=e=>{if(+e.dataset.i!==D.training.today.ans)return toast('Not quite — try again');D.training.done[S.me]=1;save();closeM();render();toast('Correct ✓')};

/* =================== events =================== */
document.addEventListener('click',e=>{const t=e.target.closest('[data-a]');if(!t)return;const f=A[t.dataset.a];if(!f)return;if(t.tagName==='LABEL'||t.querySelector&&t.querySelector('input[type=file]'))return;if(t.tagName==='A'){f(t);return}e.preventDefault();e.stopPropagation();f(t)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeM();if(e.key==='Enter'&&!e.shiftKey&&e.target.dataset&&e.target.dataset.enter==='send'){e.preventDefault();A.send()}if((e.key==='Enter'||e.key===' ')&&e.target.matches&&e.target.matches('.li.tap')){e.preventDefault();A.tOpen(e.target)}});
document.addEventListener('change',e=>{const k=e.target.dataset.ch;if(!k)return;const v=e.target.value;
 if(k==='pcr'){CART.r=v;punchSheet()}if(k==='pcn')CART.note=v;if(k==='pcrate'){CART.rates[e.target.dataset.p]=+v;punchSheet()}
 if(k==='hrfee'){D.hrco[+e.target.dataset.i].plan.fee=+v;save();toast('Fee updated')}if(k==='hra'){D.hrco[+e.target.dataset.i].plan.a=+v;save();toast('Day updated')}if(k==='hrb'){D.hrco[+e.target.dataset.i].plan.b=+v;save();toast('Day updated')}
 if(k==='tck'){const t=D.tasks.find(x=>x.id===e.target.dataset.id);t.check[+e.target.dataset.i].d=e.target.checked;save()}
 if(k==='gotfile'){const f=e.target.files&&e.target.files[0],o=document.getElementById(e.target.dataset.t+'-f');if(o)o.textContent=f?'📎 '+f.name:'No file'}
 if(k==='stmt'){const b=e.target.dataset.b,f=e.target.files&&e.target.files[0];if(!f)return;const nl=[{d:TODAY,desc:'UPI/RETAIL PAYMENT',amt:2160,m:null},{d:TODAY,desc:'ATM/CASH DEP',amt:1000,m:null}];nl.forEach(l=>{const c=D.vch.find(v=>v.amt===l.amt&&!Object.values(D.stmt).flat().some(x=>x.m===v.id));if(c)l.m=c.id});D.stmt[b]=(D.stmt[b]||[]).concat(nl);logA('Uploaded statement '+f.name);save();render();toast(f.name+' read · '+nl.filter(l=>l.m).length+' of '+nl.length+' lines matched automatically')}});
document.addEventListener('input',e=>{const k=e.target.dataset.in;if(k!=='q'&&k!=='lq')return;S[k]=e.target.value;const p=e.target.selectionStart;render();const i=document.getElementById(k);if(i){i.focus();i.setSelectionRange(p,p)}});
